def binary_tree_paths(root: Optional[TreeNode]) -> list[str]:
    if root is None:
        return []
    paths = []
    stack = [(root, str(root.val))]
    while stack:
        node, path = stack.pop()
        if node.left is None and node.right is None:
            paths.append(path)          # reached a leaf
            continue
        for child in (node.right, node.left):
            if child is not None:
                stack.append((child, path + "->" + str(child.val)))
    return paths

def expand(s: str) -> list[str]:
    groups = []
    i = 0
    while i < len(s):
        if s[i] == "{":
            j = s.index("}", i)
            groups.append(sorted(s[i + 1:j].split(",")))
            i = j + 1
        else:
            groups.append([s[i]])
            i += 1
    # Sorted groups make the product come out in lexicographic order.
    return ["".join(word) for word in itertools.product(*groups)]

def alert_names(keyName: list[str], keyTime: list[str]) -> list[str]:
    times = defaultdict(list)
    for name, t in zip(keyName, keyTime):
        times[name].append(int(t[:2]) * 60 + int(t[3:]))
    flagged = []
    for name, ts in times.items():
        ts.sort()
        # Three swipes fit in an hour iff some consecutive triple does.
        if any(ts[i + 2] - ts[i] <= 60 for i in range(len(ts) - 2)):
            flagged.append(name)
    return sorted(flagged)

def width_of_binary_tree(root: Optional[TreeNode]) -> int:
    if root is None:
        return 0
    best = 0
    level = [(root, 0)]
    while level:
        first = level[0][1]
        best = max(best, level[-1][1] - first + 1)
        nxt = []
        for node, pos in level:
            pos -= first                     # normalize to keep indices small
            if node.left:
                nxt.append((node.left, 2 * pos))
            if node.right:
                nxt.append((node.right, 2 * pos + 1))
        level = nxt
    return best

def max_distance(grid: list[list[int]]) -> int:
    n = len(grid)
    dist = [[-1] * n for _ in range(n)]
    queue = deque()
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                dist[r][c] = 0
                queue.append((r, c))
    if not queue or len(queue) == n * n:
        return -1                       # no land, or no water
    best = 0
    while queue:
        r, c = queue.popleft()
        d = dist[r][c] + 1
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < n and dist[nr][nc] == -1:
                dist[nr][nc] = d
                best = d
                queue.append((nr, nc))
    return best

