class Codec:
    ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
    PREFIX = "http://tiny.url/"

    def __init__(self):
        self.code_to_url = {}
        self.url_to_code = {}

    def _base62(self, x: int) -> str:
        digits = []
        while True:
            x, r = divmod(x, 62)
            digits.append(self.ALPHABET[r])
            if x == 0:
                return "".join(reversed(digits))

    def encode(self, longUrl: str) -> str:
        code = self.url_to_code.get(longUrl)
        if code is None:
            code = self._base62(len(self.code_to_url))   # counter based, never collides
            self.code_to_url[code] = longUrl
            self.url_to_code[longUrl] = code
        return self.PREFIX + code

    def decode(self, shortUrl: str) -> str:
        return self.code_to_url[shortUrl[len(self.PREFIX):]]

