def shortest_path_all_keys(grid: list[str]) -> int:
    m, n = len(grid), len(grid[0])
    num_keys = 0
    for r in range(m):
        for c in range(n):
            ch = grid[r][c]
            if ch == "@":
                start = (r, c)
            elif ch.islower():
                num_keys += 1
    goal = (1 << num_keys) - 1
    seen = {(start[0], start[1], 0)}
    queue = deque([(start[0], start[1], 0)])
    steps = 0
    while queue:
        steps += 1
        for _ in range(len(queue)):
            r, c, keys = queue.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if not (0 <= nr < m and 0 <= nc < n):
                    continue
                ch = grid[nr][nc]
                if ch == "#":
                    continue
                if ch.isupper() and not keys >> (ord(ch) - 65) & 1:
                    continue                      # locked and no key yet
                nk = keys | (1 << (ord(ch) - 97)) if ch.islower() else keys
                if nk == goal:
                    return steps
                if (nr, nc, nk) not in seen:
                    seen.add((nr, nc, nk))
                    queue.append((nr, nc, nk))
    return -1

