class ExamRoom:
    def __init__(self, n: int):
        self.n = n
        self.right = {-1: n}      # occupied seat (or -1) -> next occupied seat (or n)
        self.left = {n: -1}       # occupied seat (or n) -> previous occupied seat (or -1)
        self.heap = []
        self._push(-1, n)

    def _push(self, x: int, y: int) -> None:
        n = self.n
        if x == -1 and y == n:
            dist, seat = n, 0                     # empty room
        elif x == -1:
            dist, seat = y, 0                     # gap before the first student
        elif y == n:
            dist, seat = n - 1 - x, n - 1         # gap after the last student
        else:
            dist, seat = (y - x) // 2, x + (y - x) // 2
        heapq.heappush(self.heap, (-dist, seat, x, y))

    def seat(self) -> int:
        while True:
            _, s, x, y = heapq.heappop(self.heap)
            if self.right.get(x) == y:            # skip gaps that no longer exist
                break
        self.right[x], self.left[s] = s, x
        self.right[s], self.left[y] = y, s
        self._push(x, s)
        self._push(s, y)
        return s

    def leave(self, p: int) -> None:
        x, y = self.left.pop(p), self.right.pop(p)
        self.right[x], self.left[y] = y, x
        self._push(x, y)

