def minimum_moves(grid: list[list[int]]) -> int:
    sources, targets = [], []
    for r in range(3):
        for c in range(3):
            if grid[r][c] == 0:
                targets.append((r, c))
            for _ in range(grid[r][c] - 1):
                sources.append((r, c))       # one entry per extra stone
    k = len(targets)
    INF = float("inf")
    dp = [INF] * (1 << k)
    dp[0] = 0
    for mask in range(1, 1 << k):
        tr, tc = targets[bin(mask).count("1") - 1]   # the cell filled last
        for j in range(k):
            if mask >> j & 1:
                sr, sc = sources[j]
                cost = dp[mask ^ (1 << j)] + abs(sr - tr) + abs(sc - tc)
                if cost < dp[mask]:
                    dp[mask] = cost
    return dp[(1 << k) - 1]

def palindrome_pairs(words: list[str]) -> list[list[int]]:
    index = {w: i for i, w in enumerate(words)}
    result = []
    for i, w in enumerate(words):
        for cut in range(len(w) + 1):
            left, right = w[:cut], w[cut:]
            # left is a palindrome: reverse(right) + w is a palindrome.
            if left == left[::-1]:
                j = index.get(right[::-1])
                if j is not None and j != i:
                    result.append([j, i])
            # right is a palindrome: w + reverse(left) is a palindrome.
            # Skip cut == len(w); that pair is found by the branch above.
            if cut < len(w) and right == right[::-1]:
                j = index.get(left[::-1])
                if j is not None and j != i:
                    result.append([i, j])
    return result

