def robot_sim(commands: list[int], obstacles: list[list[int]]) -> int:
    blocked = set(map(tuple, obstacles))
    dirs = ((0, 1), (1, 0), (0, -1), (-1, 0))   # north, east, south, west
    x = y = d = best = 0
    for cmd in commands:
        if cmd == -2:
            d = (d + 3) % 4          # turn left
        elif cmd == -1:
            d = (d + 1) % 4          # turn right
        else:
            dx, dy = dirs[d]
            for _ in range(cmd):
                if (x + dx, y + dy) in blocked:
                    break
                x += dx
                y += dy
            best = max(best, x * x + y * y)
    return best

