class CustomStack:
    def __init__(self, maxSize: int):
        self.cap = maxSize
        self.stack = []
        self.inc = []     # inc[i] applies to element i and all elements below it

    def push(self, x: int) -> None:
        if len(self.stack) < self.cap:
            self.stack.append(x)
            self.inc.append(0)

    def pop(self) -> int:
        if not self.stack:
            return -1
        extra = self.inc.pop()
        if self.inc:
            self.inc[-1] += extra      # pass the pending addition downward
        return self.stack.pop() + extra

    def increment(self, k: int, val: int) -> None:
        if self.stack:
            self.inc[min(k, len(self.stack)) - 1] += val

