def contains_nearby_almost_duplicate(nums: list[int], indexDiff: int, valueDiff: int) -> bool:
    width = valueDiff + 1
    buckets = {}            # bucket id -> the single value in the window that maps there
    for i, x in enumerate(nums):
        b = x // width
        if b in buckets:
            return True
        if b - 1 in buckets and x - buckets[b - 1] <= valueDiff:
            return True
        if b + 1 in buckets and buckets[b + 1] - x <= valueDiff:
            return True
        buckets[b] = x
        # Keep only the last indexDiff values in the window.
        if i >= indexDiff:
            del buckets[nums[i - indexDiff] // width]
    return False

def is_ugly(n: int) -> bool:
    if n <= 0:
        return False
    for p in (2, 3, 5):
        while n % p == 0:
            n //= p
    # Only allowed primes divided n if nothing is left.
    return n == 1

