    if not arr or arr[0] is None:
        return None
    root = T(arr[0]); queue = [root]; i = 1; qi = 0
    while i < len(arr):
        node = queue[qi]; qi += 1
        if i < len(arr) and arr[i] is not None:
            node.left = T(arr[i]); queue.append(node.left)
        i += 1
        if i < len(arr) and arr[i] is not None:
            node.right = T(arr[i]); queue.append(node.right)
        i += 1
    return root

def adapt(ns, args):
    ops, params = args
    root = build_tree(ns["TreeNode"], params[0][0])
    it = ns["BSTIterator"](root)
    out = [None]
    for op, a in zip(ops[1:], params[1:]):
        out.append(getattr(it, op)(*a))
    return out

