def min_capability(nums: list[int], k: int) -> int:
    def can_rob(cap: int) -> bool:
        # Greedily take every allowed house whose left neighbor was not taken.
        count = 0
        i, n = 0, len(nums)
        while i < n:
            if nums[i] <= cap:
                count += 1
                if count >= k:
                    return True
                i += 2
            else:
                i += 1
        return False

    lo, hi = min(nums), max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_rob(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def combination_sum4(nums: list[int], target: int) -> int:
    nums = sorted(nums)
    ways = [0] * (target + 1)
    ways[0] = 1                      # the empty sequence
    for t in range(1, target + 1):
        total = 0
        for x in nums:
            if x > t:
                break                # remaining values are even larger
            total += ways[t - x]     # sequences whose last value is x
        ways[t] = total
    return ways[target]

def find_lhs(nums: list[int]) -> int:
    count = Counter(nums)
    best = 0
    for x, c in count.items():
        if x + 1 in count:
            # Take every copy of x and of x + 1.
            best = max(best, c + count[x + 1])
    return best

