def minimum_deletions(s: str) -> int:
    dp = 0        # min deletions to balance the prefix
    b_count = 0   # number of 'b' characters in the prefix
    for ch in s:
        if ch == "b":
            b_count += 1
        else:
            # Delete this 'a', or keep it and delete every earlier 'b'.
            dp = min(dp + 1, b_count)
    return dp

