def repeat_limited_string(s: str, repeatLimit: int) -> str:
    count = [0] * 26
    for ch in s:
        count[ord(ch) - 97] += 1
    out = []
    i = 25          # largest letter that may still have copies
    j = 24          # candidate for the next smaller letter
    while i >= 0:
        if count[i] == 0:
            i -= 1
            continue
        take = min(count[i], repeatLimit)
        out.append(chr(97 + i) * take)
        count[i] -= take
        if count[i] == 0:
            continue
        # Need one smaller letter to break the run.
        j = min(j, i - 1)
        while j >= 0 and count[j] == 0:
            j -= 1
        if j < 0:
            break
        out.append(chr(97 + j))
        count[j] -= 1
    return "".join(out)

def swim_in_water(grid: list[list[int]]) -> int:
    n = len(grid)
    seen = [[False] * n for _ in range(n)]
    heap = [(grid[0][0], 0, 0)]       # (highest elevation on the path, row, col)
    seen[0][0] = True
    while heap:
        t, r, c = heapq.heappop(heap)
        if r == n - 1 and c == n - 1:
            return t
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < n and not seen[nr][nc]:
                seen[nr][nc] = True
                heapq.heappush(heap, (max(t, grid[nr][nc]), nr, nc))
    return -1

