    # A snake shaped low channel forces a long winding path.
    order = []
    for r in range(n):
        if r % 4 == 0:
            order += [(r, c) for c in range(n)]
        elif r % 4 == 1:
            order.append((r, n - 1))
        elif r % 4 == 2:
            order += [(r, c) for c in range(n - 1, -1, -1)]
        else:
            order.append((r, 0))
    low = set(order)
    rest = [(r, c) for r in range(n) for c in range(n) if (r, c) not in low]
    random.shuffle(rest)
    snake = [[0] * n for _ in range(n)]
    for v, (r, c) in enumerate(order + rest):
        snake[r][c] = v
    return [[grid], [snake]]

